import com.simaoqingnian.myaccount.Ledger;
import com.simaoqingnian.myaccount.IconCatalog;
import com.simaoqingnian.myaccount.EntrySession;
import java.time.Instant;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.List;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.concurrent.atomic.AtomicReference;

/** Host-side finance checks. Does not connect to or install anything on a device. */
public final class LedgerCheck {
    private static int checks;
    private static void expect(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;}
    private static void rejects(Runnable action,String label){try{action.run();}catch(IllegalArgumentException expected){checks++;return;}throw new AssertionError(label);}
    public static void main(String[] args){
        expect(Ledger.parseAmount("0.10")+Ledger.parseAmount("0.20")==30,"exact cents");
        expect(Ledger.parseAmount("999999999.99")==Ledger.MAX_MINOR,"maximum amount");
        for(String input:new String[]{"0","-1","1.234","1e3","NaN","1000000000.00"})rejects(()->Ledger.parseAmount(input),"reject "+input);
        rejects(()->Ledger.parseDate("2026-02-30"),"impossible date");
        rejects(()->Ledger.parseDate(Ledger.today().plusDays(1).toString()),"future date");
        Ledger.Data demo=Ledger.demo();YearMonth month=YearMonth.from(Ledger.today());
        expect(Ledger.total(Ledger.month(demo,month),"expense")==231000,"current expense");
        expect(Ledger.total(Ledger.month(demo,month),"income")==1200000,"current income");
        Ledger.Report year=Ledger.report(demo,"year",Ledger.today(),"expense");
        long sum=0;for(Ledger.Bucket b:year.buckets)sum+=b.total;
        expect(sum==year.total,"year equals months");expect(year.elapsed==month.getMonthValue(),"current year divisor");
        expect(Ledger.report(demo,"month",Ledger.today(),"expense").elapsed==Ledger.today().getDayOfMonth(),"month divisor");
        int pastYear=Ledger.today().getYear()-1;
        Ledger.Report historical=Ledger.report(demo,"year",LocalDate.of(pastYear,1,1),"expense");expect(historical.elapsed==12,"full past year");
        expect(Ledger.groups(historical.entries,"expense").stream().mapToLong(g->g.total).sum()==historical.total,"category total");
        expect(Ledger.report(demo,"year",LocalDate.of(pastYear-3,1,1),"expense").total==0,"empty year");
        LocalDate jan=LocalDate.of(Ledger.today().getYear(),1,1);String now=Instant.now().toString();
        Ledger.Entry a=new Ledger.Entry("a","expense","food",100,jan.minusDays(1).toString(),"cross-year",now,now);
        Ledger.Entry b=new Ledger.Entry("b","expense","food",250,jan.toString(),"cross-year",now,now);
        Ledger.Data cross=new Ledger.Data(Arrays.asList(a,b),Collections.emptyMap(),false);Ledger.Report week=Ledger.report(cross,"week",jan,"expense");
        long expected=week.start.isAfter(jan.minusDays(1))?250:350;expect(week.total==expected,"week includes previous year when in same week");
        Map<String,Long> limits=new LinkedHashMap<>();limits.put("food",101L);rejects(()->new Ledger.Budget(100L,limits),"budget allocation");rejects(()->new Ledger.Budget(null,limits),"budget without total");
        Ledger.Entry formula=new Ledger.Entry("formula","expense","food",100,jan.toString(),"=SUM(1,2)\n\"quoted\"",now,now);
        String csv=Ledger.csv(Collections.singletonList(formula));expect(csv.startsWith("\uFEFF"),"CSV BOM");expect(csv.contains("\"'=SUM(1,2)\n\"\"quoted\"\"\""),"CSV formula and quoting");
        expect(Ledger.filter(Ledger.month(demo,month),"expense","food","咖啡",null).size()==1,"search intersection");
        expect(Ledger.categories("expense").size()==40,"40 built-in expense categories");
        expect(Ledger.categories("income").size()==12,"12 built-in income categories");
        expect(IconCatalog.ALL.size()==72,"72 icons");
        expect(new HashSet<>(IconCatalog.ALL.stream().map(i->i.id).collect(java.util.stream.Collectors.toList())).size()==72,"distinct icon ids");
        Ledger.Category pet=new Ledger.Category("custom-pet","猫咪口粮","expense","paw","#8BBAB3");
        Ledger.Category writing=new Ledger.Category("custom-writing","写稿收入","income","brush","#8BBAB3");
        List<Ledger.Category> custom=Arrays.asList(pet,writing);Ledger.Catalog catalog=new Ledger.Catalog(custom);
        expect(catalog.ofType("expense").size()==41&&catalog.get(pet.id).custom(),"custom joins catalog");
        rejects(()->new Ledger.Catalog(Arrays.asList(pet,pet)),"duplicate custom id");
        rejects(()->new Ledger.Catalog(Arrays.asList(pet,new Ledger.Category("custom-copy",pet.name,"expense","star","#AAC0A4"))),"duplicate custom name");
        rejects(()->new Ledger.Catalog(Collections.singletonList(new Ledger.Category("custom-food","餐饮","expense","star","#AAC0A4"))),"built-in name collision");
        rejects(()->new Ledger.Catalog(Collections.singletonList(Ledger.category("food"))),"cannot replace built-in id");
        rejects(()->new Ledger.Category("custom-invalid","过长的自定义项目名称超过十二个字","expense","star","#AAC0A4"),"long category name");
        rejects(()->new Ledger.Category("custom-invalid"," ","expense","star","#AAC0A4"),"blank name");
        rejects(()->new Ledger.Category("custom-invalid","猫\n粮","expense","star","#AAC0A4"),"control character");
        rejects(()->new Ledger.Category("custom-invalid","猫粮","transfer","star","#AAC0A4"),"invalid type");
        rejects(()->new Ledger.Category("custom-invalid","猫粮","expense","unknown","#AAC0A4"),"unknown icon");
        rejects(()->new Ledger.Category("custom-invalid","猫粮","expense","star","red"),"invalid color");
        Ledger.Category wide=new Ledger.Category("custom-wide","ＡＢＣ","expense","star","#AAC0A4");
        rejects(()->new Ledger.Catalog(Arrays.asList(wide,new Ledger.Category("custom-ascii","abc","expense","moon","#AAC0A4"))),"normalized duplicate name");
        expect(new Ledger.Catalog(Arrays.asList(pet,new Ledger.Category("custom-same",pet.name,"income","star","#AAC0A4"))).custom.size()==2,"names scoped by type");
        List<Ledger.Category> tooMany=new ArrayList<>();for(int i=0;i<101;i++)tooMany.add(new Ledger.Category("custom-limit-"+i,"项目"+i,"expense","star","#AAC0A4"));
        rejects(()->new Ledger.Catalog(tooMany),"custom category limit");
        expect(!IconCatalog.unused(catalog,"").isEmpty(),"spare icons exist");
        expect(IconCatalog.unused(catalog,"").stream().noneMatch(i->i.id.equals("paw")||i.id.equals("brush")),"used icons excluded");
        expect(IconCatalog.unused(catalog,writing.id).stream().anyMatch(i->i.id.equals("brush")),"own unique icon remains editable");
        Ledger.Entry personal=new Ledger.Entry("personal","expense",pet.id,1234,jan.toString(),"大袋猫粮",now,now,catalog);
        Map<String,Long> personalLimit=Collections.singletonMap(pet.id,5000L);Ledger.Budget personalBudget=new Ledger.Budget(10000L,personalLimit,catalog);
        Ledger.Data personalData=new Ledger.Data(Collections.singletonList(personal),Collections.singletonMap(month.toString(),personalBudget),false,custom);
        expect(Ledger.groups(personalData.entries,"expense").get(0).category.id.equals(pet.id),"custom report group");
        expect(Ledger.csv(personalData.entries).contains("猫咪口粮"),"custom CSV name");
        expect(Ledger.filter(personalData.entries,"expense","","猫咪口粮",null).size()==1,"custom name search");
        expect(personalData.budget(month).limits.get(pet.id)==5000,"custom budget");
        rejects(()->new Ledger.Budget(10000L,Collections.singletonMap(writing.id,100L),catalog),"income custom budget rejected");
        rejects(()->new Ledger.Data(personalData.entries,personalData.budgets,false),"missing custom category rejected");
        Ledger.Category renamed=new Ledger.Category(pet.id,"猫粮罐头","expense","star",pet.color);
        Ledger.Data renamedData=new Ledger.Data(personalData.entries,personalData.budgets,false,Arrays.asList(renamed,writing));
        expect(renamedData.entries.get(0).id.equals(personal.id)&&Ledger.csv(renamedData.entries).contains("猫粮罐头"),"rename preserves entry and refreshes display");
        List<Ledger.Entry> histories=new ArrayList<>();String old=Instant.now().minusSeconds(60).toString();
        histories.add(new Ledger.Entry("old-note","expense",pet.id,100,jan.toString(),"  大袋猫粮  ",old,old,catalog));
        histories.add(new Ledger.Entry("new-note","expense",pet.id,100,jan.toString(),"小袋猫粮",now,now,catalog));
        histories.add(new Ledger.Entry("duplicate-note","expense",pet.id,100,jan.toString(),"大袋猫粮",old,old,catalog));
        histories.add(new Ledger.Entry("blank-note","expense",pet.id,100,jan.toString()," ",now,now,catalog));
        histories.add(new Ledger.Entry("other-note","income",writing.id,100,jan.toString(),"另一项目备注",now,now,catalog));
        Ledger.Data notesData=new Ledger.Data(histories,Collections.emptyMap(),false,custom);
        expect(Ledger.noteSuggestions(notesData,"expense",pet.id).equals(Arrays.asList("小袋猫粮","大袋猫粮")),"recent notes trimmed, deduplicated, newest first");
        expect(Ledger.noteSuggestions(notesData,"income",writing.id).equals(Collections.singletonList("另一项目备注")),"notes isolated by category and type");
        expect(Ledger.noteSuggestions(notesData,"expense","food").isEmpty(),"no unrelated history fallback");
        expect(Ledger.noteSuggestions(Ledger.Data.empty(),"expense","food").isEmpty(),"new ledger has no note suggestions");
        for(int i=0;i<40;i++)histories.add(new Ledger.Entry("limit-note-"+i,"expense",pet.id,100,jan.toString(),"备注"+i,now,now,catalog));
        expect(Ledger.noteSuggestions(new Ledger.Data(histories,Collections.emptyMap(),false,custom),"expense",pet.id).size()==30,"30 recent suggestions limit");
        AtomicReference<LocalDate> clock=new AtomicReference<>(LocalDate.of(2026,11,4));EntrySession session=new EntrySession(clock::get);
        expect(session.date().equals(clock.get()),"fresh session defaults to today");
        LocalDate selected=LocalDate.of(2026,10,31);session.select(selected);expect(session.date().equals(selected),"manual date persists for next entries");
        clock.set(LocalDate.of(2026,11,5));expect(session.date().equals(selected),"manual date survives midnight");
        session.select(LocalDate.of(2026,11,2));expect(session.date().getDayOfMonth()==2,"manual change replaces remembered date");
        session.reset();expect(session.date().equals(clock.get()),"new session resets to today's date");
        clock.set(LocalDate.of(2026,11,6));expect(session.date().equals(clock.get()),"unselected default follows today");
        rejects(()->session.select(clock.get().plusDays(1)),"remembered date cannot be future");
        rejects(()->session.select(LocalDate.of(1999,12,31)),"remembered date lower bound");
        expect(new EntrySession(clock::get).date().equals(clock.get()),"remembered date is not persisted across sessions");
        System.out.println("Ledger checks passed: "+checks);
    }
}
